func stringEnd(data []byte) int {
	i := 0

	for len(data) > i {
		if data[i] != '"' {
			i++
			continue
		}

		// If it just escaped \", continue
		if i >= 1 && data[i-1] == '\\' {
			i++
			continue
		} else {
			return i + 1
		}
	}

	return -1
}
